/* IMGRLE.H -- fondo del reloj para ROLEX386.C (pantalla 640x400, campo 640x480),
 * generado con prep_img.py desde las fotos originales reloj2.png y esfera2.jpg.
 * NO EDITAR A MANO.
 *
 * Las dos fotos se alinean con una homografia (puntos SIFT), de modo que los
 * numeros y marcas del aro de los minutos coinciden y no salen duplicados.
 * Dentro del dial se usa esfera2.jpg (nitida) y fuera reloj2.png (rehaut, bisel,
 * corona y fondo negro); el borde blanco queda en r=159.5 del centro (234, 200)
 * de la franja.  La franja 494x400 va en (88, 40) del campo 640x480 (a los lados
 * solo hay negro puro, que no viaja) y el dial 340x340 en (152, 70).  La
 * ventanita de la fecha (esfera2.jpg la trae vacia) tiene el marco en x 415..446,
 * y 230..250 y el dia se pinta justo dentro, en x 417..444, y 232..248.
 *
 * Imagen: indices 0..63 = rampa de grises (el DAC de la VGA es de 6 bits: el
 * programa escribe valor/4, asi que el indice ES el nivel de gris en pantalla).
 * Indices 250..255 = colores de las agujas y de la fecha (ver ROLEX386.C).
 *
 * Regenerar:  python3 prep_img.py reloj2.png esfera2.jpg IMGRLE.H
 *
 * RLE 6+2 bits: cada byte lleva el valor en los bits 0..5 y (cuenta-1) en los
 * bits 6..7.  Cuenta 1..3: el propio byte.  Cuenta 4..255: el byte lleva 3 en
 * los bits 6..7 y el byte siguiente la cuenta.  Las rachas cruzan los bordes
 * de fila de la franja.  Decodifica exactamente STRIP_W x 400 = 197600 pixeles.
 */

